// === Tab: mySketch ===
let num = 2000;
let particles = [num];
let noiseScale = 500;
let noiseStrength = 1;
let keypress = 'a';

class squareBox{

    constructor(loc, dir, speed, color){
        this.loc = loc;
        this.size = 2;
        this.dir = dir;
        this.speed = speed;
        this.color = color;
    }

    move(){

        let mx, my, mag, angle;

        switch (keypress){

            case 'a':
                angle = noise(this.loc.x/noiseScale, this.loc.y/noiseScale, frameCount/noiseScale)*TWO_PI*noiseStrength;
                this.dir.x = cos(angle);
                this.dir.y = sin(angle);
                break;

            case 'b':
                mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - 0.5*width;
                my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - 0.5*height;
                mag = sqrt(mx*mx + my*my);
                this.dir.x = mx/mag;
                this.dir.y = my/mag;
                break;

            case 'c':
                mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.loc.x;
                my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - this.loc.y;
                mag = sqrt(mx*mx + my*my);
                this.dir.x = mx/mag;
                this.dir.y = my/mag;
                break;

            case 'd':
                mx = -(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + this.loc.x;
                my = -(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + this.loc.y;
                mag = sqrt(mx*mx + my*my);
                this.dir.x = mx/mag;
                this.dir.y = my/mag;
                break;

        }

        let vel = this.dir.copy();
        let d = 2;
        vel.mult(this.speed*d);
        this.loc.add(vel);
    }

    checkEdges(){
        if (this.loc.x < 0 || this.loc.x > width || this.loc.y < 0 || this.loc.y > height){
            this.loc.x = random(width * 1.2);
            this.loc.y = random(height * 1.2);
        }
        if (this.color > 360){
            this.color = random(0, 360)
        }
    }

    update(){
        fill(this.color);
        square(this.loc.x, this.loc.y, this.size);
    }

    run(){
        this.move();
        this.checkEdges();
        this.update();
    }

}


function setup(){
    createCanvas(windowWidth, windowHeight);
    noStroke();
    for (let i=0; i<num; i++){
        let loc = createVector(random(width*1.2), random(height), 2);
        let angle = 0;
        let dir = createVector(cos(angle), sin(angle));
        let speed = random(0.5, 2);
        let col = 255;
        particles[i] = new squareBox(loc, dir, speed, col);
    }
    background(0);
    //noCursor();

}

function windowResized(){
    resizeCanvas(windowWidth, windowHeight);
}

function keyPressed(){
    if (key == 'a' || key == 'b' || key == 'c' || key == 'd'){
        keypress = key;
    }
}

function draw(){
    //background(0);
    fill(0, 10);
    noStroke();
    rect(0, 0, width, height);
    for (let i=0; i<num; i++){
        particles[i].run();
    }
    print(keypress)
}

